/* NURiKAKURE independent 3D art studio prototype.
 * Three.js is supplied by main.js. All geometry and images here are original/generated by code.
 */
export function createArtRoom(THREE,worldCanvas,previewCanvas,paintCanvas){
 const scene=new THREE.Scene();scene.background=new THREE.Color('#c9e8e8');scene.fog=new THREE.Fog('#c9e8e8',17,38);
 const renderer=new THREE.WebGLRenderer({canvas:worldCanvas,antialias:true,alpha:false,powerPreference:'high-performance'});
 renderer.setPixelRatio(Math.min(window.devicePixelRatio||1,1.45));
 renderer.outputColorSpace=THREE.SRGBColorSpace;
 renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.32;
 const camera=new THREE.PerspectiveCamera(61,1,.12,80);
 scene.add(new THREE.HemisphereLight('#e9ffff','#a18c78',2.25));
 const sunlight=new THREE.DirectionalLight('#ffecc2',2.4);sunlight.position.set(-4,8,4);scene.add(sunlight);
 const softLight=new THREE.PointLight('#b9fff5',1.3,20);softLight.position.set(4,4,2);scene.add(softLight);
 const mat=(color,roughness=.9)=>new THREE.MeshStandardMaterial({color,roughness,metalness:.015});
 const wood=mat('#bf9374'),darkWood=mat('#987760'),teal=mat('#6b9f9b'),offWhite=mat('#f8eddb'),white=mat('#fcf6ea');
 const bookColors=['#f8bb82','#e89eae','#a7c6c9','#f0d18e','#bea5d3','#a9cba1'];
 const placed=[],colliders=[],decor=[];
 function cube(parent,x,y,z,w,h,d,material,rotate=0){
  const mesh=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);
  mesh.position.set(x,y,z);mesh.rotation.y=rotate;parent.add(mesh);return mesh;
 }
 function sphere(parent,x,y,z,r,material){
  const m=new THREE.Mesh(new THREE.SphereGeometry(r,16,12),material);m.position.set(x,y,z);parent.add(m);return m;
 }
 function cylinder(parent,x,y,z,top,bottom,height,material){
  const mesh=new THREE.Mesh(new THREE.CylinderGeometry(top,bottom,height,16),material);
  mesh.position.set(x,y,z);parent.add(mesh);return mesh;
 }
 function collision(x,z,halfW,halfD){colliders.push({x,z,halfW,halfD})}
 // Gallery floor, chalk trim, welcoming pastel walls.
 cube(scene,0,-.075,0,19,.15,15,mat('#d8bda2'));
 cube(scene,0,2.2,-7.5,19,4.5,.22,mat('#fff1de'));
 cube(scene,-9.5,2.2,0,.22,4.5,15.2,mat('#dcefe8'));
 cube(scene,9.5,2.2,0,.22,4.5,15.2,mat('#dcefe8'));
 cube(scene,0,2.2,7.5,19,4.5,.22,mat('#e8f1e6'));
 for(let i=-8;i<=8;i++){
  cube(scene,i+.5,.018,0,.018,.006,14.9,mat(i%2?'#cfb398':'#dfc4aa'));
 }
 for(let j=-7;j<=7;j++)cube(scene,0,.02,j+.5,19,.007,.013,mat('#bb9e87'));
 for(const z of [-7.35,7.35]){
  cube(scene,0,.22,z,19,.24,.13,teal);
  cube(scene,0,4.18,z,19,.1,.13,white);
 }
 // Tall windows: right and left walls.
 const windowGlass=new THREE.MeshStandardMaterial({color:'#9bd7e0',metalness:.11,roughness:.18,transparent:true,opacity:.8});
 for(const x of [-9.35,9.35])for(const z of [-4.4,.2,4.3]){
  cube(scene,x,2.8,z,.05,2.12,2.7,windowGlass);
  for(const y of [1.65,3.9])cube(scene,x,y,z,.11,.10,2.93,white);
  for(const shift of [-1.44,0,1.44])cube(scene,x,2.78,z+shift,.11,2.3,.11,white);
 }
 // Large art-room blackboard/sign painted using a browser canvas.
 function pictureTexture(draw,width=512,height=320){
  const cv=document.createElement('canvas');cv.width=width;cv.height=height;
  draw(cv.getContext('2d'),width,height);
  const tex=new THREE.CanvasTexture(cv);tex.colorSpace=THREE.SRGBColorSpace;return tex;
 }
 const boardTexture=pictureTexture((c,w,h)=>{
  c.fillStyle='#2b7275';c.fillRect(0,0,w,h);
  c.strokeStyle='#e7f6c5';c.lineWidth=8;c.strokeRect(14,14,w-28,h-28);
  c.textAlign='center';c.fillStyle='#fff4d8';c.font='bold 54px sans-serif';c.fillText('放課後の美術室',w/2,114);
  c.fillStyle='#c4efe0';c.font='bold 29px sans-serif';c.fillText('ART ROOM  /  LET’S PAINT!',w/2,169);
  for(let i=0;i<6;i++){c.fillStyle=bookColors[i];c.beginPath();c.arc(122+i*54,239,17,0,Math.PI*2);c.fill()}
 });
 const board=new THREE.Mesh(new THREE.PlaneGeometry(4.75,2.65),new THREE.MeshBasicMaterial({map:boardTexture}));
 board.position.set(0,2.65,-7.35);scene.add(board);
 cube(scene,0,1.22,-7.15,4.9,.11,.31,darkWood);
 // Ceiling fluorescent fixtures visually brighten studio without a solid ceiling.
 for(const x of [-5.5,0,5.5]){cube(scene,x,4.32,0,3.1,.1,.54,white);cube(scene,x,4.23,0,2.84,.04,.42,mat('#fff7ca'))}
 function desk(x,z){
  const deskGroup=new THREE.Group();deskGroup.position.set(x,0,z);scene.add(deskGroup);
  cube(deskGroup,0,.89,0,2.06,.14,1.16,wood);
  for(const xx of [-.84,.84])for(const zz of [-.43,.43])cube(deskGroup,xx,.43,zz,.12,.86,.12,darkWood);
  cube(deskGroup,0,.73,-.46,1.76,.25,.07,teal);
  collision(x,z,1.15,.75);
  // A little jar of paint and brushes.
  cylinder(deskGroup,.63,1.06,-.1,.13,.11,.23,mat('#efe7c9'));
  for(let i=0;i<3;i++){
   cylinder(deskGroup,.59+i*.052,1.23,-.1,.014,.014,.19,mat('#9d7767'));
   sphere(deskGroup,.59+i*.052,1.34,-.1,.026,mat(bookColors[i]));
  }
 }
 for(const p of [[-5.7,-3.5],[-2.85,2.9],[3.25,2.75],[6.1,-3.1]])desk(...p);
 function designTexture(index){
  return pictureTexture((c,w,h)=>{
   c.fillStyle=['#fff4e2','#e5f4ec','#f2edfc','#edf5fc'][index%4];c.fillRect(0,0,w,h);
   if(index%4===0){
    c.fillStyle='#f4c0a5';c.beginPath();c.arc(190,143,95,0,Math.PI*2);c.fill();
    c.fillStyle='#93cbbd';c.beginPath();c.moveTo(0,300);c.lineTo(110,98);c.lineTo(260,300);c.fill();
    c.fillStyle='#5d929d';c.beginPath();c.moveTo(166,300);c.lineTo(331,76);c.lineTo(512,300);c.fill();
   }else if(index%4===1){
    c.fillStyle='#8cbdc7';c.fillRect(0,170,512,150);c.fillStyle='#f9d59c';c.beginPath();c.arc(370,90,53,0,Math.PI*2);c.fill();
    for(let i=0;i<5;i++){c.strokeStyle=['#efa3a6','#5baf9a','#e9ab76'][i%3];c.lineWidth=24;c.beginPath();c.moveTo(46+i*90,320);c.quadraticCurveTo(100+i*53,138,32+i*97,64);c.stroke()}
   }else if(index%4===2){
    for(let i=0;i<9;i++){c.fillStyle=bookColors[i%6];c.beginPath();c.arc(60+i*51,80+(i%3)*77,45,0,Math.PI*2);c.fill()}
   }else{
    c.fillStyle='#e9ca94';c.fillRect(0,0,512,320);
    c.strokeStyle='#a4d2d4';c.lineWidth=42;for(let i=0;i<6;i++){c.beginPath();c.moveTo(20,i*60);c.lineTo(480,320-i*35);c.stroke()}
   }
  });
 }
 function easel(x,z,rotation,index){
  const g=new THREE.Group();g.position.set(x,0,z);g.rotation.y=rotation;scene.add(g);
  cube(g,-.43,.9,0,.10,1.8,.12,darkWood,.09);
  cube(g,.43,.9,0,.10,1.8,.12,darkWood,-.09);
  cube(g,0,1.24,.15,.09,2.32,.1,darkWood);
  cube(g,0,.55,.12,1.55,.11,.25,wood);
  cube(g,0,1.56,.11,1.45,1.20,.09,white);
  const art=new THREE.Mesh(new THREE.PlaneGeometry(1.32,1.08),new THREE.MeshStandardMaterial({map:designTexture(index),roughness:1}));
  art.position.set(0,1.56,.169);g.add(art);
  collision(x,z,.75,.58);
 }
 easel(-6.9,3.6,.38,0);easel(6.6,3.7,-.45,1);easel(-6.75,-4.85,.25,2);easel(6.75,-5.0,-.22,3);
 // Open supply shelves, with colored book spines and storage baskets.
 function shelving(x,z,rot){
  const g=new THREE.Group();g.position.set(x,0,z);g.rotation.y=rot;scene.add(g);
  cube(g,-1,.95,0,.15,1.9,.73,wood);cube(g,1,.95,0,.15,1.9,.73,wood);
  for(const y of [.16,.75,1.34,1.88])cube(g,0,y,0,2.1,.10,.78,wood);
  for(let i=0;i<11;i++)cube(g,-.77+i*.15,1.01,0,.10,.42,.5,mat(bookColors[i%6]),Math.sin(i)*.07);
  for(let i=0;i<5;i++)cylinder(g,-.7+i*.34,1.52,0,.14,.13,.26,mat(bookColors[(i+2)%6]));
  collision(x,z,1.3,.6);
 }
 shelving(-5.2,-6.3,.04);shelving(5.3,-6.3,-.04);
 // Central carpet / decorative chalk circles.
 const carpetMat=new THREE.MeshStandardMaterial({color:'#8fc8c5',roughness:1,transparent:true,opacity:.42});
 const carpet=new THREE.Mesh(new THREE.CylinderGeometry(2.5,2.5,.014,48),carpetMat);
 carpet.position.set(.2,.028,.1);scene.add(carpet);
 // Little plant beside room door.
 const pot=mat('#f2ab85'),leaf=mat('#6bab87');
 cylinder(scene,8.2,.34,5.8,.34,.30,.68,pot);
 for(let i=0;i<7;i++){
  const a=i*Math.PI*2/7;
  const stem=sphere(scene,8.2+Math.cos(a)*.24,1.06+Math.sin(i*8)*.18,5.8+Math.sin(a)*.24,.29,leaf);
  stem.scale.y=1.65;
 }
 // Avatar: canvas painting texture shared across head/body/arms/legs.
 const paintTexture=new THREE.CanvasTexture(paintCanvas);paintTexture.colorSpace=THREE.SRGBColorSpace;
 paintTexture.wrapS=THREE.RepeatWrapping;paintTexture.wrapT=THREE.ClampToEdgeWrapping;
 paintTexture.anisotropy=Math.min(renderer.capabilities.getMaxAnisotropy(),4);
 const patternMat=new THREE.MeshStandardMaterial({map:paintTexture,roughness:.93,metalness:0});
 function avatar(){
  const root=new THREE.Group(),body=new THREE.Group();root.add(body);
  const torso=new THREE.Mesh(new THREE.CylinderGeometry(.40,.43,.93,28),patternMat);torso.position.y=1.00;body.add(torso);
  const head=new THREE.Mesh(new THREE.SphereGeometry(.36,26,20),patternMat);head.position.y=1.69;body.add(head);
  const armGeo=new THREE.CylinderGeometry(.135,.15,.80,16);
  const arms=[];
  for(const dir of [-1,1]){
   const arm=new THREE.Group();arm.position.set(dir*.52,1.33,0);body.add(arm);
   const mesh=new THREE.Mesh(armGeo,patternMat);mesh.position.y=-.33;arm.add(mesh);arms.push(arm);
   const leg=new THREE.Mesh(new THREE.CylinderGeometry(.16,.17,.65,16),patternMat);
   leg.position.set(dir*.22,.36,0);body.add(leg);
  }
  // The face always points towards local -Z.
  const eyeMat=mat('#27454a');for(const x of [-.14,.14])sphere(body,x,1.73,-.306,.047,eyeMat);
  const mouth=new THREE.Mesh(new THREE.TorusGeometry(.10,.012,8,16,Math.PI),eyeMat);
  mouth.position.set(0,1.56,-.335);mouth.rotation.z=Math.PI;body.add(mouth);
  return {root,body,arms};
 }
 const character=avatar();scene.add(character.root);character.root.position.set(0,0,2.1);
 // Separate small 3D viewer shares the live avatar texture.
 const previewScene=new THREE.Scene();previewScene.background=new THREE.Color('#e2f3ed');
 const previewCamera=new THREE.PerspectiveCamera(37,1,.1,25);previewCamera.position.set(0,1.45,4.65);previewCamera.lookAt(0,1.02,0);
 previewScene.add(new THREE.HemisphereLight('#fffaf0','#819fb2',2.4));
 const previewDir=new THREE.DirectionalLight('#fff8e6',1.7);previewDir.position.set(-3,6,6);previewScene.add(previewDir);
 const previewAvatar=avatar();previewScene.add(previewAvatar.root);
 const previewRenderer=new THREE.WebGLRenderer({canvas:previewCanvas,antialias:true,alpha:false,powerPreference:'low-power'});
 previewRenderer.setPixelRatio(Math.min(window.devicePixelRatio||1,1.4));previewRenderer.outputColorSpace=THREE.SRGBColorSpace;
 previewRenderer.toneMapping=THREE.ACESFilmicToneMapping;previewRenderer.toneMappingExposure=1.24;
 let yaw=.64,pitch=.35,zoom=5.9,walking=0,paintMode=false,elapsed=0,viewPointer=null;
 const motion={x:0,z:0};
 function setViewport(){
  const a=worldCanvas.getBoundingClientRect();
  if(a.width>=3&&a.height>=3){renderer.setSize(Math.floor(a.width),Math.floor(a.height),false);camera.aspect=a.width/a.height;camera.updateProjectionMatrix()}
  const b=previewCanvas.getBoundingClientRect();
  if(b.width>=3&&b.height>=3){previewRenderer.setSize(Math.floor(b.width),Math.floor(b.height),false);previewCamera.aspect=b.width/b.height;previewCamera.updateProjectionMatrix()}
 }
 function isWalkable(x,z){
  if(x<-8.75||x>8.75||z<-6.8||z>6.7)return false;
  const radius=.36;
  return !colliders.some(b=>Math.abs(x-b.x)<b.halfW+radius&&Math.abs(z-b.z)<b.halfD+radius);
 }
 function move(dx,dz,dt){
  const len=Math.hypot(dx,dz);if(len<.09){walking=0;return}
  dx/=Math.max(1,len);dz/=Math.max(1,len);
  // Camera yaw is measured from the avatar to the camera; local forward points away.
  const vx=dx*Math.cos(yaw)-dz*Math.sin(yaw);
  const vz=-dx*Math.sin(yaw)-dz*Math.cos(yaw);
  const nx=character.root.position.x+vx*3.15*dt,nz=character.root.position.z+vz*3.15*dt;
  if(isWalkable(nx,character.root.position.z))character.root.position.x=nx;
  if(isWalkable(character.root.position.x,nz))character.root.position.z=nz;
  const heading=Math.atan2(-vx,-vz);
  const delta=Math.atan2(Math.sin(heading-character.root.rotation.y),Math.cos(heading-character.root.rotation.y));
  character.root.rotation.y+=delta*Math.min(1,dt*13);
  walking=1;
 }
 function orbit(dx,dy){yaw-=dx*.0065;pitch=THREE.MathUtils.clamp(pitch+dy*.004,.12,.95)}
 function centerView(){yaw=.64;pitch=.35;zoom=5.9}
 function zoomView(delta){zoom=THREE.MathUtils.clamp(zoom+delta,3.5,9)}
 function update(dt,axes){
  dt=Math.min(.05,Math.max(0,dt));elapsed+=dt;
  if(!paintMode)move(axes.x||0,axes.z||0,dt);
  const bob=walking?Math.sin(elapsed*16)*.06:Math.sin(elapsed*2.5)*.016;
  character.body.position.y=bob;
  for(let i=0;i<character.arms.length;i++)character.arms[i].rotation.x=walking?Math.sin(elapsed*13+i*Math.PI)*.34:Math.sin(elapsed*2+i)*.07;
  const pos=character.root.position;
  const height=1.50+Math.sin(pitch)*zoom*.70,reach=Math.cos(pitch)*zoom;
  const desired=new THREE.Vector3(pos.x+Math.sin(yaw)*reach,height,pos.z+Math.cos(yaw)*reach);
  camera.position.lerp(desired,Math.min(1,dt*9));
  camera.lookAt(pos.x,1.28,pos.z);
  if(paintMode){previewAvatar.root.rotation.y+=dt*.45;previewAvatar.body.position.y=Math.sin(elapsed*2.7)*.035}
 }
 function draw(){
  renderer.render(scene,camera);
  if(paintMode)previewRenderer.render(previewScene,previewCamera);
 }
 function setPaintMode(yes){
  paintMode=!!yes;walking=0;previewAvatar.root.rotation.y=0;
  if(paintMode){setViewport();previewRenderer.render(previewScene,previewCamera)}
 }
 function refreshPaint(){paintTexture.needsUpdate=true}
 function destroy(){renderer.dispose();previewRenderer.dispose();paintTexture.dispose()}
 setViewport();
 camera.position.set(3.8,3.7,7);camera.lookAt(0,1.25,0);draw();
 return {setViewport,update,draw,orbit,centerView,zoomView,setPaintMode,refreshPaint,destroy,
   getPosition(){return {x:character.root.position.x,z:character.root.position.z}},
   getCamera(){return {yaw,pitch,zoom}},
   getPaintTexture(){return paintTexture}};
}
